'use client';

import React, { useEffect, useState, Suspense } from 'react';
import { useSearchParams, useRouter } from 'next/navigation';
import { Result, Button, Spin, Card, Typography, Descriptions } from 'antd';
import { CheckCircleFilled, CloseCircleFilled, ShoppingOutlined, EyeOutlined } from '@ant-design/icons';
import { apiClient } from '@/lib/api-client';
import { formatCurrency } from '@/lib/format';

const { Title, Text } = Typography;

function PaymentReturnContent() {
  const searchParams = useSearchParams();
  const router = useRouter();

  const [loading, setLoading] = useState(true);
  const [result, setResult] = useState<any>(null);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  // Lấy các tham số cơ bản từ query URL
  const vnpResponseCode = searchParams.get('vnp_ResponseCode');
  const vnpTxnRef = searchParams.get('vnp_TxnRef');
  const vnpAmount = searchParams.get('vnp_Amount');
  const vnpOrderInfo = searchParams.get('vnp_OrderInfo');
  const vnpTransactionNo = searchParams.get('vnp_TransactionNo');
  const vnpBankCode = searchParams.get('vnp_BankCode');

  // Trích xuất Order ID dự phòng từ vnpTxnRef (dạng "11_1791685735903_365dcd") hoặc vnp_OrderInfo ("Thanh toan don hang #11")
  const extractedOrderId = (() => {
    if (vnpTxnRef && vnpTxnRef.includes('_')) {
      const parts = vnpTxnRef.split('_');
      if (parts[0] && !isNaN(Number(parts[0]))) {
        return parts[0];
      }
    }
    if (vnpOrderInfo) {
      const match = vnpOrderInfo.match(/#(\d+)/);
      if (match) return match[1];
    }
    return null;
  })();

  useEffect(() => {
    const processResult = async () => {
      try {
        setLoading(true);
        // Gửi toàn bộ query parameters sang backend để xác thực chữ ký và cập nhật giao dịch
        const queryString = searchParams.toString();
        const res: any = await apiClient.get(`/payments/vnpay/return?${queryString}`);
        setResult(res.data?.data || res.data || res);
      } catch (err: any) {
        setErrorMsg(err?.response?.data?.message || err?.message || 'Không thể xác thực giao dịch');
      } finally {
        setLoading(false);
      }
    };

    if (searchParams && searchParams.toString()) {
      processResult();
    } else {
      setLoading(false);
      setErrorMsg('Không tìm thấy thông tin giao dịch trả về');
    }
  }, [searchParams]);

  if (loading) {
    return (
      <div style={{ textAlign: 'center', padding: '100px 0' }}>
        <Spin size="large" tip="Đang kiểm tra và xác nhận kết quả giao dịch VNPay..." />
      </div>
    );
  }

  const orderId = result?.orderId || extractedOrderId;
  const isSuccess = vnpResponseCode === '00';
  const amount = result?.amount || (vnpAmount ? Number(vnpAmount) / 100 : 0);

  return (
    <div style={{ maxWidth: 700, margin: '40px auto', padding: '0 20px' }}>
      <Card style={{ borderRadius: 16, boxShadow: '0 4px 20px rgba(0,0,0,0.06)' }}>
        <Result
          status={isSuccess ? 'success' : 'error'}
          title={isSuccess ? 'Thanh toán thành công!' : 'Thanh toán không thành công'}
          subTitle={
            isSuccess
              ? 'Đơn hàng của bạn đã được thanh toán và đang được xử lý.'
              : (result?.message || errorMsg || 'Giao dịch bị huỷ hoặc có lỗi xảy ra trong quá trình thanh toán.')
          }
          extra={[
            orderId && (
              <Button
                type="primary"
                key="order"
                icon={<EyeOutlined />}
                size="large"
                style={{ borderRadius: 8 }}
                onClick={() => router.push(`/orders/${orderId}`)}
              >
                Xem chi tiết đơn hàng #{orderId}
              </Button>
            ),
            <Button
              key="history"
              icon={<ShoppingOutlined />}
              size="large"
              style={{ borderRadius: 8 }}
              onClick={() => router.push('/orders/history')}
            >
              Lịch sử đơn hàng
            </Button>,
          ]}
        >
          <div style={{ marginTop: 24, backgroundColor: '#fafafa', padding: 20, borderRadius: 12 }}>
            <Descriptions title="Chi tiết giao dịch" column={1} size="small" bordered>
              {orderId && (
                <Descriptions.Item label="Mã đơn hàng">
                  <strong>#{orderId}</strong>
                </Descriptions.Item>
              )}
              {amount > 0 && (
                <Descriptions.Item label="Số tiền thanh toán">
                  <span style={{ color: isSuccess ? '#52c41a' : '#ff4d4f', fontWeight: 600 }}>
                    {formatCurrency(amount)}
                  </span>
                </Descriptions.Item>
              )}
              {vnpBankCode && (
                <Descriptions.Item label="Ngân hàng">
                  {vnpBankCode}
                </Descriptions.Item>
              )}
              {vnpTransactionNo && (
                <Descriptions.Item label="Mã giao dịch VNPay">
                  {vnpTransactionNo}
                </Descriptions.Item>
              )}
              <Descriptions.Item label="Trạng thái">
                {isSuccess ? (
                  <span style={{ color: '#52c41a', fontWeight: 600 }}>Thành công (00)</span>
                ) : (
                  <span style={{ color: '#ff4d4f', fontWeight: 600 }}>
                    Thất bại (Mã: {vnpResponseCode || 'Lỗi'})
                  </span>
                )}
              </Descriptions.Item>
            </Descriptions>
          </div>
        </Result>
      </Card>
    </div>
  );
}

import ClientLayout from '@/components/shared/ClientLayout';

export default function PaymentReturnPage() {
  return (
    <ClientLayout>
      <Suspense fallback={
        <div style={{ textAlign: 'center', padding: '100px 0' }}>
          <Spin size="large" />
        </div>
      }>
        <PaymentReturnContent />
      </Suspense>
    </ClientLayout>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { Typography, Row, Col, Button, message, Space, Divider, Radio, Tag, Breadcrumb, Skeleton, theme } from "antd";
import { ShoppingCartOutlined, HeartOutlined, ThunderboltOutlined, HomeOutlined } from "@ant-design/icons";
import { useParams, useRouter } from "next/navigation";
import ClientLayout from "@/components/shared/ClientLayout";
import Link from "next/link";
import { useThemeStore } from "@/store/themeStore";
import { useCartStore } from "@/store/cartStore";

const { Title, Text, Paragraph } = Typography;

const COLORS = ["Titan Tự nhiên", "Titan Đen", "Titan Trắng", "Titan Xanh"];
const STORAGES = ["256GB", "512GB", "1TB"];

export default function ProductDetailPage() {
  const params = useParams();
  const router = useRouter();
  const [product, setProduct] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [messageApi, contextHolder] = message.useMessage();

  const [selectedColor, setSelectedColor] = useState(COLORS[0]);
  const [selectedStorage, setSelectedStorage] = useState(STORAGES[0]);
  const { isDarkMode } = useThemeStore();
  const { addToCart, setCartVisible } = useCartStore();
  const { token } = theme.useToken();

  useEffect(() => {
    const fetchProduct = async () => {
      try {
        // Workaround: GET /api/products/{id} is failing (500) due to Redis @Cacheable error on backend.
        // Since we cannot modify the backend, we fetch the product list and find the product by ID.
        const res = await fetch(`/api/products?page=0&size=100`);
        if (res.ok) {
          const json = await res.json();
          const list = json.data?.content || json.data || [];
          const found = list.find((p: any) => p.id === parseInt(params.id as string));
          if (found) {
            setProduct(found);
          } else {
            console.warn("Product not found in list");
          }
        }
      } catch (error) {
        console.error("Failed to fetch product:", error);
      } finally {
        setLoading(false);
      }
    };
    if (params.id) {
      fetchProduct();
    }
  }, [params.id]);

  const handleAddToCart = () => {
    if (!product) return;
    const attributes = [];
    if (hasColor) attributes.push(selectedColor);
    if (hasStorage) attributes.push(selectedStorage);
    const attrString = attributes.length > 0 ? ` (${attributes.join(', ')})` : '';

    addToCart({
      productId: product.id,
      name: `${product.name}${attrString}`,
      price: product.price * priceMultiplier,
      quantity: 1,
      image: product.imageUrl || "https://placehold.co/200x200?text=No+Image"
    });
    setCartVisible(true);
    messageApi.success(`Đã thêm ${product?.name} vào giỏ hàng`);
  };

  const handleBuyNow = () => {
    if (!product) return;
    const attributes = [];
    if (hasColor) attributes.push(selectedColor);
    if (hasStorage) attributes.push(selectedStorage);
    const attrString = attributes.length > 0 ? ` (${attributes.join(', ')})` : '';

    addToCart({
      productId: product.id,
      name: `${product.name}${attrString}`,
      price: product.price * priceMultiplier,
      quantity: 1,
      image: product.imageUrl || "https://placehold.co/1000x1000?text=No+Image"
    });
    setCartVisible(false);
    router.push("/orders/new");
  };

  if (loading) {
    return (
      <ClientLayout>
        <div style={{ padding: "40px 10%", maxWidth: 1200, margin: "0 auto", backgroundColor: isDarkMode ? '#0f0f11' : '#f5f5f7' }}>
          <Skeleton active paragraph={{ rows: 10 }} />
        </div>
      </ClientLayout>
    );
  }

  if (!product) {
    return (
      <ClientLayout>
        <div style={{ padding: "100px 10%", textAlign: "center", backgroundColor: token.colorBgBase }}>
          <Title level={3} style={{ color: token.colorText }}>Không tìm thấy sản phẩm</Title>
          <Button type="primary" onClick={() => router.push("/")} style={{ marginTop: 20 }}>Về trang chủ</Button>
        </div>
      </ClientLayout>
    );
  }

  const productNameLower = product.name?.toLowerCase() || '';
  // Kiểm tra phụ kiện (ốp lưng, bao da, dán màn hình, cáp sạc, tai nghe,...) -> không hiển thị màu/dung lượng
  const isAccessory = 
    productNameLower.includes('ốp') || 
    productNameLower.includes('op') || 
    productNameLower.includes('bao da') || 
    productNameLower.includes('case') || 
    productNameLower.includes('cường lực') || 
    productNameLower.includes('kính') || 
    productNameLower.includes('dán') || 
    productNameLower.includes('sạc') || 
    productNameLower.includes('cáp') || 
    productNameLower.includes('dây');

  // Chỉ hiển thị màu sắc và dung lượng với Điện thoại thật (không phải ốp lưng hay phụ kiện)
  const isPhone = 
