"use client";

import React, { useEffect, useState } from "react";
import { Result, Button, Card } from "antd";
import { useRouter } from "next/navigation";
import Link from "next/link";

export default function ActivateSuccessPage() {
  const router = useRouter();
  const [email, setEmail] = useState<string>("");

  useEffect(() => {
    const searchParams = new URLSearchParams(window.location.search);
    const emailParam = searchParams.get("email");
    if (emailParam) {
      setEmail(emailParam);
    }
  }, []);

  return (
    <div style={{ display: "flex", justifyContent: "center", alignItems: "center", minHeight: "100vh", backgroundColor: "#f0f2f5" }}>
      <Card style={{ width: 500, borderRadius: 12, boxShadow: "0 4px 12px rgba(0,0,0,0.1)" }}>
        <Result
          status="success"
          title="Xác thực tài khoản thành công!"
          subTitle={
            email 
              ? <span>Tài khoản <b>{email}</b> của bạn đã sẵn sàng.</span>
              : "Tài khoản của bạn đã được kích hoạt thành công và sẵn sàng sử dụng."
          }
          extra={[
            <Button 
              type="primary" 
              key="login" 
              size="large"
              style={{ borderRadius: 8, width: "100%", maxWidth: 200 }}
              onClick={() => {
                if (email) {
                  router.push(`/auth/login?email=${encodeURIComponent(email)}`);
                } else {
                  router.push("/auth/login");
                }
              }}
            >
              Đi đến Đăng nhập
            </Button>
          ]}
        />
      </Card>
    </div>
  );
}

"use client";

import React, { useState } from "react";
import { Table, Button, Tag, Space, Popconfirm, message } from "antd";
import { PlusOutlined } from "@ant-design/icons";
import { useSearchParams, useRouter } from "next/navigation";

import { useCustomers, useDeleteCustomer } from "@/features/customers/hooks";

import { Customer } from "@/features/customers/types";
import { CustomerModal } from "@/features/customers/components/CustomerModal";

export default function CustomersPage() {
  const router = useRouter();
  const searchParams = useSearchParams();

  const page = Number(searchParams.get("page")) || 1;

  const {
    data: customersData,
    isLoading,
    isError,
  } = useCustomers({ page, size: 20 });

  const { mutate: deleteCustomer } = useDeleteCustomer();

  const [messageApi, contextHolder] = message.useMessage();

  const [isModalVisible, setIsModalVisible] = useState(false);
  const [selectedCustomer, setSelectedCustomer] = useState<
    Customer | undefined
  >();

  const isAdminUser = (c: Customer) => {
    const email = (c.email || "").toLowerCase().trim();
    const name = (c.name || "").toLowerCase().trim();
    return (
      email.includes("admin") ||
      name.includes("admin") ||
      name.includes("quản trị viên") ||
      (c as any).role === "ADMIN"
    );
  };

  const rawList: Customer[] = Array.isArray(customersData?.content)
    ? customersData.content
    : Array.isArray(customersData)
      ? customersData
      : [];

  const customers: Customer[] = rawList.filter((c: Customer) => !isAdminUser(c));

  const totalElements = customersData?.totalElements
    ? Math.max(0, customersData.totalElements - (rawList.length - customers.length))
    : customers.length;

  const showModal = (customer?: Customer) => {
    setSelectedCustomer(customer);
    setIsModalVisible(true);
  };

  const handleTableChange = (pagination: { current?: number }) => {
    const params = new URLSearchParams(searchParams.toString());

    params.set("page", String(pagination.current || 1));

    router.push(`?${params.toString()}`);
  };

  const handleDelete = (id: number) => {
    deleteCustomer(id, {
      onSuccess: () => {
        messageApi.success("Xóa khách hàng thành công");
      },
      onError: (err: any) => {
        messageApi.error(
          err?.response?.data?.message ||
            "Không thể xóa khách hàng này. Khách hàng có thể đã phát sinh đơn hàng.",
        );
      },
    });
  };

  const columns = [
    {
      title: "Họ tên",
      dataIndex: "name",
      key: "name",
      render: (value: string) => (
        <span className="customer-name">{value || "—"}</span>
      ),
    },
    {
      title: "Email",
      dataIndex: "email",
      key: "email",
      render: (value: string) => (
        <span className="customer-email">{value || "—"}</span>
      ),
    },
    {
      title: "Số điện thoại",
      dataIndex: "phone",
      key: "phone",
      width: 200,
      render: (value: string) => <span>{value || "—"}</span>,
    },
    {
      title: "Trạng thái",
      dataIndex: "status",
      key: "status",
      width: 170,
      render: (status: string) => {
        const isActive = status === "ACTIVE";

        return (
          <Tag
            className={
              isActive
                ? "customer-status customer-status-active"
                : "customer-status customer-status-inactive"
            }
          >
            {status || "UNKNOWN"}
          </Tag>
        );
      },
    },
    {
      title: "Thao tác",
      key: "action",
      width: 140,
      render: (_: unknown, record: Customer) => (
        <Space
          size={5}
          separator={<span className="customer-action-separator">·</span>}
        >
          <Button
            type="link"
            className="customer-action-link"
            onClick={() => showModal(record)}
          >
            Sửa
          </Button>

          <Popconfirm
            title="Xác nhận xóa"
            description="Bạn có chắc chắn muốn xóa khách hàng này?"
            onConfirm={() => handleDelete(record.id)}
            okText="Xóa"
            cancelText="Hủy"
          >
            <Button type="link" className="customer-action-link" danger>
              Xóa
            </Button>
          </Popconfirm>
        </Space>
      ),
    },
  ];

  return (
    <>
      {contextHolder}

      <div className="customer-management">
        {/* Tiêu đề và nút thêm */}
        <div className="customer-management-header">
          <h2>Quản lý khách hàng</h2>

          <Button
            type="primary"
            icon={<PlusOutlined />}
            className="customer-add-button"
            onClick={() => showModal()}
          >
            Thêm khách hàng
          </Button>
        </div>

        {/* Bảng khách hàng */}
        <Table<Customer>
          className="customer-management-table"
          columns={columns}
          dataSource={
            isError
              ? []
              : customers.map((customer) => ({
                  ...customer,
                  key: customer.id,
                }))
          }
          rowKey="id"
          loading={isLoading}
          pagination={{
            current: page,
            pageSize: 20,
            total: totalElements,
            showSizeChanger: false,
            showTotal: (total) => `Tổng ${total} khách hàng`,
          }}
          onChange={handleTableChange}
          locale={{
            emptyText: isError
              ? "Có lỗi xảy ra khi tải dữ liệu"
              : "Không có khách hàng nào",
          }}
          scroll={{ x: 700 }}
        />
      </div>

      {/* Modal thêm và sửa khách hàng */}
      <CustomerModal
        open={isModalVisible}
        onClose={() => setIsModalVisible(false)}
        customer={selectedCustomer}
      />

    </>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { Table, Button, Card, Row, Col, Statistic, Select, Space, Tag, message } from "antd";
import { FileWordOutlined, FilePdfOutlined, DownloadOutlined, BarChartOutlined, CheckCircleOutlined, DollarOutlined, ShoppingCartOutlined, ReloadOutlined } from "@ant-design/icons";
import { fetchAllOrders } from "@/features/dashboard/api";
import dayjs from "dayjs";
import isBetween from "dayjs/plugin/isBetween";
dayjs.extend(isBetween);

export default function ReportsPage() {
  const [orders, setOrders] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [wordExporting, setWordExporting] = useState(false);
  const [timeRange, setTimeRange] = useState<"today" | "7days" | "30days" | "all">("30days");
  const [statusFilter, setStatusFilter] = useState<string>("ALL");

  const loadData = async () => {
    setLoading(true);
    try {
      const data = await fetchAllOrders();
      setOrders(data);
    } catch (e) {
      console.error(e);
      message.error("Không thể tải danh sách đơn hàng cho báo cáo!");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  // Lọc dữ liệu theo thời gian và trạng thái
  const now = dayjs();
  const filteredOrders = orders.filter((order) => {
    // Lọc theo trạng thái
    if (statusFilter !== "ALL") {
      if (statusFilter === "PAID") {
        const isPaid =
          order.paymentStatus === "PAID" ||
          order.status === "PAID" ||
          order.status === "COMPLETED" ||
          order.status === "PROCESSING";
        if (!isPaid) return false;
      } else {
        if (order.status !== statusFilter) return false;
      }
    }

    // Lọc theo thời gian
    const orderDate = dayjs(order.createdAt);
    if (timeRange === "today") {
      return orderDate.format("YYYY-MM-DD") === now.format("YYYY-MM-DD");
    }
    if (timeRange === "7days") {
      return orderDate.isAfter(now.subtract(7, "day").startOf("day"));
    }
    if (timeRange === "30days") {
      return orderDate.isAfter(now.subtract(30, "day").startOf("day"));
    }
    return true;
  });

  // Tính các chỉ số KPI
  let totalRevenue = 0;
  let paidCount = 0;
  filteredOrders.forEach((o) => {
    const isPaid =
      o.paymentStatus === "PAID" ||
      o.status === "PAID" ||
      o.status === "COMPLETED" ||
      o.status === "PROCESSING";

    if (isPaid) {
      totalRevenue += Number(o.totalAmount) || 0;
      paidCount++;
    }
  });

  const totalCount = filteredOrders.length;
  const avgOrderValue = paidCount > 0 ? Math.round(totalRevenue / paidCount) : 0;

  // 1. Xuất file Word (.docx) từ backend API /api/export/word
  const handleExportWord = async () => {
    setWordExporting(true);
    try {
      const res = await fetch("/api/export/word", {
        headers: {
          Authorization: `Bearer ${localStorage.getItem("token") || ""}`,
        },
      });
      if (!res.ok) throw new Error("Xuất file Word thất bại");
      const blob = await res.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `BaoCao_DoanhThu_${dayjs().format("YYYYMMDD_HHmm")}.docx`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      window.URL.revokeObjectURL(url);
      message.success("Xuất báo cáo Word thành công!");
    } catch (e: any) {
      message.error(e?.message || "Lỗi khi xuất file Word");
    } finally {
      setWordExporting(false);
    }
  };

  // 2. Xuất hóa đơn Jasper PDF từ backend /api/jasper/orders/{id}/pdf
  const handleExportJasperPdf = async (orderId: number) => {
    try {
      message.loading({ content: `Đang xuất hóa đơn Jasper PDF #${orderId}...`, key: "pdf" });
      const res = await fetch(`/api/jasper/orders/${orderId}/pdf`, {
        headers: {
          Authorization: `Bearer ${localStorage.getItem("token") || ""}`,
        },
      });
      if (!res.ok) {
        // Fallback sang endpoint hóa đơn PDF chuẩn
        const resFallback = await fetch(`/api/orders/${orderId}/pdf`, {
          headers: {
            Authorization: `Bearer ${localStorage.getItem("token") || ""}`,
          },
        });
        if (!resFallback.ok) throw new Error("Không thể tạo hóa đơn PDF cho đơn hàng này");
        const blob = await resFallback.blob();
        triggerDownloadBlob(blob, `Invoice_Order_${orderId}.pdf`);
        message.success({ content: "Tải hóa đơn PDF thành công!", key: "pdf" });
        return;
      }
      const blob = await res.blob();
      triggerDownloadBlob(blob, `Jasper_Invoice_Order_${orderId}.pdf`);
      message.success({ content: "Xuất hóa đơn Jasper PDF thành công!", key: "pdf" });
    } catch (e: any) {
      message.error({ content: e?.message || "Lỗi xuất PDF", key: "pdf" });
    }
  };

  const triggerDownloadBlob = (blob: Blob, filename: string) => {
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    window.URL.revokeObjectURL(url);
  };

  // 3. Xuất file CSV / Excel
  const handleExportCsv = () => {
    if (filteredOrders.length === 0) {
      message.warning("Không có dữ liệu đơn hàng trong kỳ để xuất!");
      return;
    }
    const headers = ["Mã đơn", "Khách hàng", "Email", "Tổng tiền (VNĐ)", "Trạng thái", "Thanh toán", "Ngày tạo"];
    const rows = filteredOrders.map((o) => [
      `#${o.id}`,
      `"${o.customerName || "Khách lẻ"}"`,
      `"${o.customerEmail || ""}"`,
      o.totalAmount || 0,
      o.status,
      o.paymentStatus || "UNPAID",
      dayjs(o.createdAt).format("DD/MM/YYYY HH:mm:ss"),
    ]);

    const csvContent = "\uFEFF" + [headers.join(","), ...rows.map((e) => e.join(","))].join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    triggerDownloadBlob(blob, `BaoCao_DonHang_${dayjs().format("YYYYMMDD_HHmm")}.csv`);
