"use client";

import React, { useState, useEffect, useCallback } from "react";
import { Table, Button, Select, Tooltip, App } from "antd";
import { ReloadOutlined } from "@ant-design/icons";
import type { ColumnsType, TablePaginationConfig } from "antd/es/table";
import { apiClient } from "@/lib/api-client";
import dayjs from "dayjs";

export interface FailedEmailItem {
  id: string | number;
  recipient: string;        // Người nhận
  emailType: string;        // Loại mail
  retryCount: number;       // Số lần thử
  lastError: string;        // Lỗi gần nhất (lấy từ BE ghi lại)
  createdAt: string;        // Thời điểm tạo
  status: "FAILED" | "PENDING" | "SENT" | "RESOLVED" | string;
}

export default function FailedEmailsPage() {
  const { message } = App.useApp();
  const [emails, setEmails] = useState<FailedEmailItem[]>([]);
  const [loading, setLoading] = useState<boolean>(false);
  const [statusFilter, setStatusFilter] = useState<string>("FAILED");
  const [actionLoadingId, setActionLoadingId] = useState<string | number | null>(null);

  // Quản lý phân trang Server-side
  const [pagination, setPagination] = useState({
    current: 1,
    pageSize: 20,
    total: 0,
  });

  // Gọi trực tiếp API backend lấy danh sách mail gửi lỗi
  const fetchEmails = useCallback(async (page = 1, size = 20, status = statusFilter) => {
    setLoading(true);
    try {
      // Backend thường phân trang 0-indexed hoặc 1-indexed, ở đây truyền cả page/size
      const res: any = await apiClient.get("/admin/failed-emails", {
        params: {
          page: page - 1,
          size: size,
          status: status === "ALL" ? undefined : status,
        },
      });

      // Hỗ trợ cấu trúc trả về Spring Pageable: res.data.content hoặc res.data
      const content = res?.data?.content || res?.content || (Array.isArray(res?.data) ? res.data : []);
      const totalElements = res?.data?.totalElements || res?.totalElements || content.length;

      // Chuẩn hoá dữ liệu theo các trường BE trả về
      const mappedList: FailedEmailItem[] = content.map((item: any) => ({
        id: item.id,
        recipient: item.recipient || item.recipientEmail || item.to || item.userEmail || "",
        emailType: item.emailType || item.type || item.template || "ORDER_PAID",
        retryCount: item.retryCount ?? item.retries ?? item.retryTimes ?? 0,
        lastError: item.lastError || item.errorMessage || item.reason || item.message || "",
        createdAt: item.createdAt || item.createdDate || item.time || new Date().toISOString(),
        status: item.status || "FAILED",
      }));

      setEmails(mappedList);
      setPagination((prev) => ({
        ...prev,
        current: page,
        pageSize: size,
        total: totalElements,
      }));
    } catch (err: any) {
      const errorMsg = err?.response?.data?.message || "Không thể tải danh sách mail gửi lỗi từ máy chủ!";
      message.error(errorMsg);
      setEmails([]);
    } finally {
      setLoading(false);
    }
  }, [statusFilter]);

  // Tải lại khi thay đổi filter hoặc mount
  useEffect(() => {
    fetchEmails(1, pagination.pageSize, statusFilter);
  }, [fetchEmails, statusFilter]);

  // Xử lý gửi lại từng dòng
  const handleResend = async (record: FailedEmailItem) => {
    // 1. Kiểm tra trạng thái cục bộ trước
    if (record.status !== "FAILED") {
      message.error("Mail không còn ở FAILED");
      fetchEmails(pagination.current, pagination.pageSize);
      return;
    }

    setActionLoadingId(record.id);
    try {
      // 2. Gửi request retry lên BE
      const res: any = await apiClient.post(`/admin/failed-emails/${record.id}/retry`);
      message.success(res?.data?.message || "Đã gửi lại thành công!");
    } catch (err: any) {
      // 3. Nếu BE trả về mail không còn ở FAILED thì báo lỗi
      const serverMessage = err?.response?.data?.message || "";
      if (err?.response?.status === 400 || serverMessage.toLowerCase().includes("failed")) {
        message.error("Mail không còn ở FAILED");
      } else {
        message.error(serverMessage || "Gửi lại thất bại, vui lòng thử lại sau!");
      }
    } finally {
      setActionLoadingId(null);
      // Gửi xong -> tải lại danh sách
      fetchEmails(pagination.current, pagination.pageSize);
    }
  };

  const handleTableChange = (newPagination: TablePaginationConfig) => {
    fetchEmails(
      newPagination.current || 1,
      newPagination.pageSize || 20,
      statusFilter
    );
  };

  // Cấu hình các cột hiển thị theo đúng yêu cầu
  const columns: ColumnsType<FailedEmailItem> = [
    {
      title: "Người nhận",
      dataIndex: "recipient",
      key: "recipient",
      width: "22%",
      render: (text: string) => <span style={{ fontWeight: 500, color: "#1f1f1f" }}>{text}</span>,
    },
    {
      title: "Loại mail",
      dataIndex: "emailType",
      key: "emailType",
      width: "16%",
      render: (text: string) => <span style={{ fontFamily: "monospace", fontSize: 13 }}>{text}</span>,
    },
    {
      title: "Số lần thử",
      dataIndex: "retryCount",
      key: "retryCount",
      width: "12%",
      align: "center",
      render: (count: number) => <span>{count}</span>,
    },
    {
      title: "Lỗi gần nhất",
      dataIndex: "lastError",
      key: "lastError",
      width: "26%",
      render: (errorMsg: string) => (
        <Tooltip title={errorMsg} placement="topLeft">
          <div
            style={{
              maxWidth: 240,
              overflow: "hidden",
              textOverflow: "ellipsis",
              whiteSpace: "nowrap",
              color: "#cf1322",
              cursor: "pointer",
            }}
          >
            {errorMsg || "(Không có log lỗi)"}
          </div>
        </Tooltip>
      ),
    },
    {
      title: "Tạo lúc",
      dataIndex: "createdAt",
      key: "createdAt",
      width: "14%",
      render: (time: string) => (
        <span style={{ color: "#595959" }}>
          {time ? dayjs(time).format("DD/MM/YYYY HH:mm") : "-"}
        </span>
      ),
    },
    {
      title: "Thao tác",
      key: "action",
      width: "10%",
      align: "center",
      render: (_: any, record: FailedEmailItem) => (
        <Button
          type="default"
          style={{
            borderColor: "#1677ff",
            color: "#1677ff",
            borderRadius: 6,
            fontWeight: 500,
            minWidth: 80,
          }}
          loading={actionLoadingId === record.id}
          disabled={record.status !== "FAILED"}
          onClick={() => handleResend(record)}
        >
          Gửi lại
        </Button>
      ),
    },
  ];

  return (
    <div
      style={{
        background: "#ffffff",
        border: "1px solid #d9d9d9",
        borderRadius: 8,
        padding: "20px 24px",
        margin: "0 auto",
      }}
    >
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: 16,
        }}
      >
        <h2 style={{ margin: 0, fontSize: 18, fontWeight: 700, color: "#111111" }}>
          Mail gửi lỗi
        </h2>

        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <span style={{ fontSize: 14, color: "#333333" }}>Trạng thái:</span>
          <Select
            value={statusFilter}
            onChange={(val) => setStatusFilter(val)}
            style={{ width: 140, height: 36 }}
            options={[
              { value: "FAILED", label: "FAILED" },
              { value: "ALL", label: "Tất cả" },
              { value: "PENDING", label: "PENDING" },
              { value: "SENT", label: "SENT" },
            ]}
          />
          {/* <Button
            icon={<ReloadOutlined />}
            onClick={() => fetchEmails(pagination.current, pagination.pageSize, statusFilter)}
            loading={loading}
            style={{ height: 36, padding: "0 16px" }}
          >
            Làm mới
          </Button> */}
        </div>
      </div>

      <Table
        columns={columns}
        dataSource={emails}
        rowKey="id"
        loading={loading}
        onChange={handleTableChange}
        pagination={{
          current: pagination.current,
          pageSize: pagination.pageSize,
          total: pagination.total,
          defaultPageSize: 20,
          pageSizeOptions: ["10", "20", "50"],
          showSizeChanger: true,
          locale: { items_per_page: "/ trang" },
        }}
      />
    </div>
  );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import {
  Table,
  Button,
  Tag,
  Select,
  message,
  Card,
  Popconfirm,
  Typography,
} from "antd";
import { apiClient } from "@/lib/api-client";

const { Title, Text } = Typography;

export interface EmployeeUser {
  id: number;
  email: string;
  name?: string;
  username?: string;
  role: "ADMIN" | "PRODUCT_OWNER" | "USER" | string;
  status: "ACTIVE" | "INACTIVE" | "LOCKED" | string;
  createdAt?: string;
}

export default function EmployeesPage() {
  const [employees, setEmployees] = useState<EmployeeUser[]>([]);
  const [loading, setLoading] = useState<boolean>(false);
  const [messageApi, contextHolder] = message.useMessage();

  // 1. Tải danh sách tài khoản thật từ Backend
  const fetchEmployees = useCallback(async () => {
    setLoading(true);
    try {
      let rawList: any[] = [];

      // Ưu tiên endpoint lấy toàn bộ user quản trị
      try {
        const res: any = await apiClient.get("/admin/users");
        rawList = res.data?.data || res.data?.content || res.data || [];
      } catch (adminErr) {
        // Fallback sang endpoint lấy danh sách tài khoản nếu chưa có route admin riêng
        const resFallback: any = await apiClient.get("/customers?page=0&size=100");
        rawList = resFallback.data?.content || resFallback.data?.data || resFallback.data || [];
      }

      if (!Array.isArray(rawList)) {
        rawList = [];
      }

      // Map chuẩn xác từng trường từ DB vào giao diện
      const mapped: EmployeeUser[] = rawList.map((u: any) => ({
        id: u.id,
        email: u.email,
        name: u.fullName || u.name || u.username || u.email?.split("@")[0],
        username: u.username || u.email?.split("@")[0],
        // Lấy đúng role từ DB, mặc định USER nếu backend null
        role: (u.role || u.roles?.[0]?.name || u.roles?.[0] || "USER").toUpperCase(),
        // Lấy status từ DB hoặc cờ is_active / enabled
        status: (u.status || (u.enabled === false || u.isActive === 0 ? "INACTIVE" : "ACTIVE")).toUpperCase(),
        createdAt: u.createdAt || u.created_at,
      }));

      setEmployees(mapped);
    } catch (err: any) {
      console.error("Lỗi fetch users:", err);
      messageApi.error(err.response?.data?.message || "Không thể tải danh sách tài khoản từ máy chủ!");
    } finally {
      setLoading(false);
    }
  }, [messageApi]);

  useEffect(() => {
    fetchEmployees();
  }, [fetchEmployees]);

  // 2. Cập nhật vai trò thực tế vào Backend
  const handleChangeRole = async (employee: EmployeeUser, newRole: string) => {
    const oldRole = employee.role;
    // Cập nhật optimistic UI trước
    setEmployees((prev) =>
      prev.map((e) => (e.id === employee.id ? { ...e, role: newRole } : e))
    );

    try {
      // Endpoint cập nhật role (thay đổi URL nếu backend của bạn dùng PUT /admin/users/{id} hoặc khác)
      await apiClient.patch(`/admin/users/${employee.id}/role`, { role: newRole });
      messageApi.success(`Đã cập nhật [${employee.email}] thành: ${newRole}`);
    } catch (err: any) {
      // Rollback lại state cũ nếu backend trả về lỗi (403, 500, ...)
      setEmployees((prev) =>
        prev.map((e) => (e.id === employee.id ? { ...e, role: oldRole } : e))
      );
      messageApi.error(
        err.response?.data?.message || `Lỗi cập nhật quyền cho [${employee.email}] trên máy chủ!`
      );
    }
  };

  // 3. Đổi trạng thái (Active / Inactive) vào Backend
  const handleToggleStatus = async (employee: EmployeeUser) => {
    const nextStatus = employee.status === "ACTIVE" ? "INACTIVE" : "ACTIVE";
    const oldStatus = employee.status;

    setEmployees((prev) =>
      prev.map((e) => (e.id === employee.id ? { ...e, status: nextStatus } : e))
    );

    try {
      await apiClient.patch(`/admin/users/${employee.id}/status`, { status: nextStatus });
      messageApi.success(`Đã chuyển trạng thái sang: ${nextStatus === "ACTIVE" ? "Hoạt động" : "Tạm khóa"}`);
    } catch (err: any) {
      // Rollback lại nếu backend từ chối
      setEmployees((prev) =>
        prev.map((e) => (e.id === employee.id ? { ...e, status: oldStatus } : e))
      );
      messageApi.error(err.response?.data?.message || "Không thể cập nhật trạng thái trên máy chủ!");
    }
  };

  const columns = [
    {
      title: "Mã",
      dataIndex: "id",
      key: "id",
      width: 80,
      render: (id: number) => <span style={{ fontWeight: 600, color: "#1677ff" }}>#{id}</span>,
    },
    {
      title: "Tài khoản nhân sự",
      key: "name",
      render: (_: any, record: EmployeeUser) => (
        <div>
          <div style={{ fontWeight: 600, color: "#1f1f1f", fontSize: 14 }}>
            {record.name || record.username}
          </div>
          <div style={{ fontSize: 12, color: "#8c8c8c" }}>{record.email}</div>
        </div>
      ),
    },
    {
      title: "Phân quyền vai trò",
      dataIndex: "role",
      key: "role",
      render: (role: string, record: EmployeeUser) => (
        <Select
          value={role}
          style={{ width: 230 }}
          onChange={(newRole) => handleChangeRole(record, newRole)}
          options={[
            {
              value: "PRODUCT_OWNER",
              label: (
                <span>
                  <Tag color="cyan" style={{ marginRight: 6 }}>KHO</Tag>
                  Quản lý kho & Sản phẩm
                </span>
              ),
            },
            {
              value: "ADMIN",
              label: (
                <span>
                  <Tag color="red" style={{ marginRight: 6 }}>ADMIN</Tag>
                  Quản trị viên toàn quyền
                </span>
              ),
            },
            {
              value: "USER",
              label: (
                <span>
                  <Tag color="default" style={{ marginRight: 6 }}>USER</Tag>
                  Nhân viên tiêu chuẩn
                </span>
              ),
            },
          ]}
        />
      ),
    },
    {
      title: "Quyền hạn trong kho",
      key: "scope",
      render: (_: any, record: EmployeeUser) => {
        if (record.role === "ADMIN") {
          return <Tag color="gold">Toàn quyền hệ thống & Kho hàng</Tag>;
        }
        if (record.role === "PRODUCT_OWNER") {
          return <Tag color="blue">Quản lý tồn kho, duyệt xuất nhập sản phẩm</Tag>;
        }
        return <Tag color="default">Xem sản phẩm cơ bản</Tag>;
      },
    },
    {
      title: "Trạng thái",
      dataIndex: "status",
      key: "status",
      align: "center" as const,
      width: 130,
      render: (status: string) => {
        const isActive = status === "ACTIVE";
        return (
          <Tag color={isActive ? "success" : "default"}>
            {isActive ? "Đang làm việc" : "Tạm khóa"}
          </Tag>
        );
      },
    },
    {
      title: "Thao tác",
      key: "action",
      align: "center" as const,
      width: 120,
      render: (_: any, record: EmployeeUser) => (
        <Popconfirm
          title={record.status === "ACTIVE" ? "Tạm khóa quyền tài khoản này?" : "Kích hoạt lại tài khoản?"}
          onConfirm={() => handleToggleStatus(record)}
          okText="Đồng ý"
          cancelText="Hủy"
        >
          <Button
            type="text"
            danger={record.status === "ACTIVE"}
            style={{ fontWeight: 500 }}
          >
            {record.status === "ACTIVE" ? "Tạm khóa" : "Kích hoạt"}
          </Button>
        </Popconfirm>
      ),
    },
  ];

  return (
    <Card
      style={{
        borderRadius: 12,
        border: "1px solid #dcdfe6",
        boxShadow: "none",
      }}
      styles={{ body: { padding: "20px 24px" } }}
    >
      {contextHolder}

      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: 16,
        }}
      >
        <div>
          <Title level={4} style={{ margin: 0, fontWeight: 700, fontSize: 18, color: "#1f1f1f" }}>
            Phân quyền Nhân viên Quản lý kho
          </Title>
          <Text type="secondary" style={{ fontSize: 13 }}>
            Tự chọn vai trò trực tiếp (PRODUCT_OWNER: Quản lý kho & sản phẩm, ADMIN: Toàn quyền) cho nhân sự trong hệ thống
          </Text>
        </div>
      </div>

      <Table
        columns={columns}
        dataSource={employees.map((e) => ({ ...e, key: e.id }))}
        loading={loading}
        pagination={{ pageSize: 10 }}
      />
    </Card>
  );
}

