"use client";

import React, { useState, useEffect } from "react";
import { Layout, Dropdown, message, ConfigProvider, theme } from "antd";
import {
  LayoutDashboard,
  Package,
  Users,
  UserCheck,
  ShoppingCart,
  BarChart,
  Mail,
  FileText,
  LogOut,
  Search,
  Bell,
  ChevronDown,
} from "lucide-react";
import { useRouter, usePathname } from "next/navigation";
import styles from "./AdminLayout.module.scss";

const { Sider } = Layout;

export default function AdminLayout({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<any>(null);
  const router = useRouter();
  const pathname = usePathname();
  const [messageApi, contextHolder] = message.useMessage();

  useEffect(() => {
    localStorage.removeItem("admin_theme");
    document.documentElement.classList.remove("dark");
  }, []);

  useEffect(() => {
    try {
      const cachedUser = localStorage.getItem("user");
      if (cachedUser) setUser(JSON.parse(cachedUser));
    } catch {}

    const fetchUser = async () => {
      const token = localStorage.getItem("token");
      if (token) {
        try {
          const res = await fetch("/api/auth/me", {
            headers: { Authorization: `Bearer ${token}` },
          });
          if (res.ok) {
            const data = await res.json();
            const userData = data.data || data;
            setUser(userData);
            localStorage.setItem("user", JSON.stringify(userData));
          }
        } catch {}
      }
    };
    fetchUser();
  }, []);

  const handleLogout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("user");
    messageApi.success("Đã đăng xuất thành công");
    router.push("/auth/login");
  };

  const menuItems = [
    { key: "/admin", label: "Tổng quan", icon: LayoutDashboard },
    { key: "/admin/products", label: "Sản phẩm", icon: Package },
    { key: "/admin/customers", label: "Khách hàng", icon: Users },
