import { useQuery, useMutation, useQueryClient, Query } from '@tanstack/react-query';
import { orderApi } from './api';
import { OrderDetail } from './types';

export const useOrders = (params: any, options?: { refetchInterval?: number | false }) => {
  return useQuery({
    queryKey: ['orders', params],
    queryFn: () => orderApi.getOrders(params),
    refetchInterval: options?.refetchInterval ?? 3000, // Tự động làm mới mỗi 3 giây
    refetchOnWindowFocus: true, // Tự động làm mới ngay khi chuyển tab quay lại
  });
};

export const useOrderDetail = (orderId: string | number) => {
  return useQuery({
    queryKey: ['order', orderId],
    queryFn: () => orderApi.getOrderDetail(orderId),
    enabled: !!orderId,
    refetchInterval: (query: Query<OrderDetail, Error>) => {
      const order = query.state.data;
      // Nếu đã hoàn thành hoặc đã huỷ thì giảm tần suất hoặc dừng, còn đang PENDING / AWAITING_PAYMENT thì poll mỗi 3 giây
      if (order?.status === 'CANCELLED' || (order?.paymentStatus === 'PAID' && order?.status === 'COMPLETED')) {
        return false;
      }
      return 3000;
    },
    refetchOnWindowFocus: true,
  });
};

export const useOrder = useOrderDetail;

export const useCreateOrder = () => {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (data: any) => orderApi.createOrder(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['orders'] });
    },
  });
};

export const useUpdateOrderItems = () => {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ id, data }: { id: string | number; data: any }) =>
      orderApi.updateOrderItems(id, data),
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ['order', variables.id] });
      queryClient.invalidateQueries({ queryKey: ['orders'] });
    },
  });
};

export type TransitionRule = {
  currentStatus: string;
  label: string;
  targetStatus: string;
  confirmTitle: string;
  actionType: 'cancel_ticket' | 'confirm_ticket' | 'patch_status' | 'approve_refund' | 'reject_refund';
};

export const ORDER_TRANSITIONS: TransitionRule[] = [
  {
    currentStatus: 'PENDING',
    label: 'Xác nhận đơn',
    targetStatus: 'CONFIRMED',
    confirmTitle: 'Xác nhận đơn hàng này (Duyệt) để Khách có thể thanh toán?',
    actionType: 'confirm_ticket'
  },
  {
    currentStatus: 'PENDING',
    label: 'Từ chối / Hủy',
    targetStatus: 'CANCELLED',
    confirmTitle: 'Bạn chắc chắn muốn hủy đơn hàng này?',
    actionType: 'cancel_ticket'
  },
  {
    currentStatus: 'PROCESSING',
    label: 'Đã giao hàng (Hoàn thành)',
    targetStatus: 'COMPLETED',
    confirmTitle: 'Đánh dấu đơn hàng là đã giao thành công (Hoàn thành)?',
    actionType: 'patch_status'
  },
  {
    currentStatus: 'REFUND_REQUESTED',
    label: 'Chấp nhận hoàn tiền',
    targetStatus: 'REFUNDED',
    confirmTitle: 'Bạn đồng ý hoàn tiền cho đơn hàng này?',
    actionType: 'approve_refund'
  },
  {
    currentStatus: 'REFUND_REQUESTED',
    label: 'Từ chối hoàn tiền',
    targetStatus: 'PROCESSING', // Backend decides exact fallback state, UI just triggers reject
    confirmTitle: 'Từ chối yêu cầu hoàn tiền của khách hàng?',
    actionType: 'reject_refund'
  }
];

export const getAvailableTransitions = (status: string, paymentStatus?: string): TransitionRule[] => {
  return ORDER_TRANSITIONS.filter(t => t.currentStatus === status);
};

